svg.script:
(function () {
  const XHTML = "http://www.w3.org/1999/xhtml";
  const LABELS = { mc: "Eaglercraft", vault: "Umbra", noct: "Nocturne", casino: "Cup Casino", board: "Board Games" };

  // Private content is fetched from your backend at launch time (nothing else is stored in this file)
  const BACKEND = "https://script.google.com/macros/s/YOUR-PROJECT-ID/exec";
  const REMOTE = { vault: "umbra", casino: "casino", board: "board", noct: "noct" };
  const KKEY = "launcherHub.key";

  const $ = (id) => document.getElementById(id);
  const setStatus = (msg) => { $("statusText").textContent = msg; };

  // ---------- about:blank ----------
  function openBlank(loadingMsg) {
    const win = window.open("about:blank", "_blank");
    if (!win) { setStatus("Pop-up blocked! Allow pop-ups for this page and try again."); return null; }
    if (loadingMsg) {
      try {
        win.document.write('<body style="margin:0;background:#05060d;color:#b7b3c7;font:15px system-ui,sans-serif;display:grid;place-items:center;height:100vh">' + loadingMsg + '</body>');
      } catch (e) {}
    }
    return win;
  }
  function render(win, html, base) {
    let out = html;
    if (base && !/<base\s/i.test(out)) out = '<base href="' + base + '">' + out;
    win.document.open();
    win.document.write(out);
    win.document.close();
  }

  // ---------- recently launched ----------
  const RKEY = "launcherHub.recent";
  function getRecent() {
    try { return JSON.parse(localStorage.getItem(RKEY) || "[]").filter((k) => LABELS[k]); } catch (e) { return []; }
  }
  function remember(id) {
    try { localStorage.setItem(RKEY, JSON.stringify([id].concat(getRecent().filter((x) => x !== id)).slice(0, 4))); } catch (e) {}
    renderRecent();
  }
  function renderRecent() {
    const box = $("recentList");
    while (box.firstChild) box.removeChild(box.firstChild);
    const r = getRecent();
    if (!r.length) {
      const h = document.createElementNS(XHTML, "span");
      h.setAttribute("class", "hint");
      h.textContent = "Nothing launched yet.";
      box.appendChild(h);
      return;
    }
    r.forEach((id) => {
      const b = document.createElementNS(XHTML, "button");
      b.setAttribute("type", "button");
      b.setAttribute("class", "chip-btn");
      b.setAttribute("data-action", id === "mc" ? "mc-launch" : id);
      b.textContent = LABELS[id];
      box.appendChild(b);
    });
  }

  // ---------- Eaglercraft (logic is loaded from the backend) ----------
  let mcMod = null, mcTry = null;
  function loadMc() {
    if (mcMod) return Promise.resolve(mcMod);
    if (!mcTry) mcTry = (async () => {
      const r = await callBackend("mc");
      if (!r || !r.ok) { mcTry = null; throw new Error((r && REASONS[r.status]) || "Unavailable"); }
      const code = await r.text();
      mcMod = new Function("ctx", code)({ $: $, setStatus: setStatus, render: render, remember: remember });
      return mcMod;
    })().catch((e) => { mcTry = null; throw e; });
    return mcTry;
  }
  async function launchMc() {
    const win = openBlank("Loading Eaglercraft…");
    if (!win) return;
    try { const m = await loadMc(); await m.launch(win); }
    catch (err) { try { win.close(); } catch (e) {} setStatus("Eaglercraft: " + (err.message || "Unavailable")); }
  }
  async function clearMc() {
    try { const m = await loadMc(); await m.clear(); }
    catch (err) { setStatus("Eaglercraft: " + (err.message || "Unavailable")); }
  }

  // ---------- simple embedded pages ----------
  function openPage(id, html) {
    const win = openBlank();
    if (!win) return;
    render(win, html);
    remember(id);
    setStatus(LABELS[id] + " launched!");
  }


  // ---------- remote pages (served by the private backend) ----------
  function getKey() { try { return localStorage.getItem(KKEY) || ""; } catch (e) { return ""; } }
  // Google Apps Script always answers with HTTP 200 and a JSON envelope: {ok, body} or {ok:false, error, message}
  const CODES = { shutdown: 410, origin: 403, key: 401, rate: 429, disabled: 503, unknown: 404, server: 500 };
  // Loads the backend with a script tag (JSONP). Browsers don't apply the cross-site fetch rules to script tags.
  function jsonp(url) {
    return new Promise((resolve, reject) => {
      const cb = "__hub" + Math.random().toString(36).slice(2);
      const s = document.createElementNS(XHTML, "script");
      const t = setTimeout(() => { cleanup(); reject(new Error("timed out")); }, 60000);
      function cleanup() { clearTimeout(t); try { delete window[cb]; } catch (e) { window[cb] = undefined; } if (s.parentNode) s.parentNode.removeChild(s); }
      window[cb] = (d) => { cleanup(); resolve(d); };
      s.onerror = () => { cleanup(); reject(new Error("script blocked or unreachable")); };
      s.setAttribute("src", url + "&callback=" + cb);
      document.documentElement.appendChild(s);
    });
  }
  async function rawCall(url) {
    try { return await jsonp(url); }
    catch (e1) {
      const res = await fetch(url);
      return await res.json();
    }
  }
  async function callBackend(m) {
    for (let i = 0; i < 2; i++) {
      const k = getKey();
      const env = await rawCall(BACKEND + "?m=" + m + (k ? "&key=" + encodeURIComponent(k) : "") + "&t=" + Date.now());
      if (env && env.ok) {
        return { ok: true, status: 200, text: async () => env.body, json: async () => env, clone() { return this; } };
      }
      const status = CODES[env && env.error] || 500;
      if (status === 401 && i === 0) {
        const entered = window.prompt("Access key:");
        if (entered) { try { localStorage.setItem(KKEY, entered.trim()); } catch (e) {} continue; }
      }
      const msg = (env && env.message) || "";
      return { ok: false, status, text: async () => msg, json: async () => env, clone() { return this; } };
    }
  }
  const REASONS = {
    410: "This launcher has been shut down by its owner.",
    403: "This copy of the launcher is not authorized.",
    401: "A valid access key is required.",
    429: "Too many requests. Wait a minute and try again.",
    503: "This section is switched off right now.",
    404: "Not found."
  };
  async function openRemote(id) {
    const win = openBlank("Loading " + LABELS[id] + "...");
    if (!win) return;
    setStatus("Loading " + LABELS[id] + "...");
    let msg = "";
    try {
      const r = await callBackend(REMOTE[id]);
      if (r && r.ok) {
        render(win, await r.text());
        remember(id);
        setStatus(LABELS[id] + " launched!");
        return;
      }
      msg = (r && REASONS[r.status]) || "The server returned an error.";
      if (r) { let d = ""; try { d = (await r.clone().text()).slice(0, 90).replace(/\s+/g, " "); } catch (e) {} msg += " [HTTP " + r.status + (d ? ": " + d : "") + "]"; }
    } catch (e) {
      msg = "Could not reach the server. Check your connection. [" + (e && e.name) + ": " + (e && e.message) + "]";
    }
    try { win.document.body.textContent = msg; } catch (e) {}
    setStatus(LABELS[id] + ": " + msg);
  }
  async function checkBackend() {
    let mods = null, why = "";
    if (/YOUR-PROJECT/.test(BACKEND)) why = "Backend URL not set";
    else try {
      const r = await callBackend("status");
      if (r && r.ok) mods = (await r.json()).modules; else why = (r && REASONS[r.status]) || "Offline";
    } catch (e) { why = "Offline (check the web app link and sharing)"; }
    Object.keys(REMOTE).forEach((id) => {
      const b = document.querySelector('[data-action="' + id + '"]');
      if (!b) return;
      const on = mods && mods[REMOTE[id]];
      b.disabled = !on;
      b.setAttribute("title", on ? "" : (why || "Switched off"));
      if (!on) b.textContent = why && why.length < 40 ? why : "Unavailable";
    });
    ["mc-launch", "mc-clear"].forEach((a) => {
      const b = document.querySelector('[data-action="' + a + '"]');
      if (b) { b.disabled = !(mods && mods.mc); if (!(mods && mods.mc)) b.setAttribute("title", why || "Switched off"); }
    });
    if (mods && mods.mc) { try { (await loadMc()).refresh(); } catch (e) {} }
    else { $("cacheText").textContent = why || "Unavailable"; }
    if (why) setStatus(why);
  }

  const ACTIONS = {
    "mc-launch": launchMc,
    "mc-clear": clearMc,
    vault: () => openRemote("vault"),
    noct: () => openRemote("noct"),
    casino: () => openRemote("casino"),
    board: () => openRemote("board")
  };
  document.addEventListener("click", (e) => {
    const t = e.target && e.target.closest ? e.target.closest("[data-action]") : null;
    const fn = t && ACTIONS[t.getAttribute("data-action")];
    if (fn) fn();
  });

  function fit() {
    const root = document.querySelector(".root");
    const k = window.innerWidth / (screen.width || window.innerWidth);
    if (navigator.maxTouchPoints > 0 && screen.width < 700 && k > 1.25) {
      root.style.width = (100 / k) + "%";
      root.style.height = (100 / k) + "%";
      root.style.transformOrigin = "0 0";
      root.style.transform = "scale(" + k + ")";
    } else {
      root.style.width = "100%"; root.style.height = "100%"; root.style.transform = "";
    }
    root.setAttribute("class", "root" + (root.clientWidth < 640 ? " narrow" : ""));
  }
  window.addEventListener("resize", fit);
  window.addEventListener("orientationchange", fit);
  fit();

  renderRecent();
  checkBackend();
})();
